import{_ as o}from"./chunks/cover_image.CgCjIhXF.js";import{_ as a,c as t,ag as i,o as p}from"./chunks/framework.kMCHP7uL.js";const u=JSON.parse('{"title":"前言","description":"","frontmatter":{"outline":"deep","showVersion":false},"headers":[],"relativePath":"prologue.md","filePath":"prologue.md"}'),r={name:"prologue.md"};function s(l,e,c,g,n,d){return p(),t("div",null,e[0]||(e[0]=[i('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">⚠️ 警告</p><p>Zig 這門語言並不適合計算機初學者，如果你已經對計算機有了基礎的瞭解，並且能夠較為熟練的掌握一門高級編程語言，我才推薦你來學習它。</p><p>確保你的 zig 版本是最新的 <code>release</code> 版本，再進行學習！</p></div><p>有過多營銷號說 zig 已經是 C 的替代品了，這是完全不正確的。將來或許會是，但現在肯定不是，目前 zig 只是一個有那麼一丁點熱度的高級語言。</p><p>你可能會疑惑，為什麼要學習一門如此 <code>low level</code> 的語言，C 難道不好嗎？</p><p>C 很好，非常好，它非常成功，以至於 C 現在已經不再是一門語言，而是一個標準。 你可能會注意到，現在跨語言調用，基本都是遵循的 C ABI，包括編譯出來的各種庫供其他語言使用，也都是 C 可以使用的動態鏈接庫。</p><p>但由於歷史原因，C 到現在已經處於一種較為割裂的存在，它本身有著一套自己的標準，但是不同的編譯器卻有著不同的“專屬語法”，也就是不同編譯器支持的語法實際上是 C 的超集！同時 C 本身沒有一個屬於自己的包管理器，各式各樣的第三方包管理器。。。五花八門，像 meson、cmake、xmake、vcpkg，而且均有上手難度。</p><p>歷史上有不少語言都自詡是 C 的替代品，像 Odin、Ada、Modula-2、Go，他們在某種程度上都算是失敗了，當然 Zig 的未來也可能是這樣子，成為一個不是 C 的替代品，單獨的一門語言，或許有人使用。但就現在來看，我認為 Zig 還是很有希望成為 C 的代替品的，目前的語法均是圍繞著語義明確化，減少隱式的執行，更高效的錯誤跟蹤。</p><p>或許可能有人會跟我說 Rust 比 Zig 好，我要說的是你說的基本是對的，目前情況來看，Rust 的的確確比 Zig 好很多，更為完善的生態，更多能拿得出手的代表項目，以及相較 Zig 龐大很多的社區等等，但是在未來誰說的準呢？更何況 Rust 和 Zig 並不是一個賽道上的東西，在我看來，Rust 的目標是 C++ 的替代，因此我更願意稱之為“披著高抽象皮的 low level 語言”，Zig 的目標則是 C，而且目前 Zig 的特性也的確在這個方向發展。</p><p>Zig 的社區需要更多的人來構建，所以我寫了這個文檔，幫助新人來更好的理解和學習 Zig！</p><p><img src="'+o+'" alt="Cover Image" title="Cover Image" loading="lazy"></p>',10)]))}const C=a(r,[["render",s]]);export{u as __pageData,C as default};
